import boto3
from datetime import datetime, timedelta

def summarize_audit_events():
    client = boto3.client('cloudtrail')
    end_time = datetime.utcnow()
    start_time = end_time - timedelta(days=7)

    response = client.lookup_events(
       LookupAttributes=[
           {
               'AttributeKey': 'EventName',
               'AttributeValue': 'AssumeRole'
           }
       ],
      StartTime=start_time,
      EndTime=end_time
    )

    audit_events = response['Events']
    summary = {
        'total_events': len(audit_events),
        'events': []
    }

    for event in audit_events:
        event_summary = {
            'event_time': event['EventTime'].strftime('%Y-%m-%d %H:%M:%S'),
            'user_identity': event['Username']
        }
        summary['events'].append(event_summary)

    return summary

if __name__ == '__main__':
    summary = summarize_audit_events()
    print(summary)

from typing import Any, Dict, Union


class FederatedLoginRequest:
    def __init__(self, provider: str, access_token: str):
        self.provider = provider
        self.access_token = access_token

    def to_dict(self) -> Dict[str, Any]:
        return {
            'provider': self.provider,
            'access_token': self.access_token,
        }

    @classmethod
    def from_dict(cls, data: Dict[str, Any]) -> 'FederatedLoginRequest':
        return cls(
            provider=data['provider'],
            access_token=data['access_token'],
        )


class FederatedLoginResponse:
    def __init__(self, user_id: str, email: str, name: str):
        self.user_id = user_id
        self.email = email
        self.name = name

    def to_dict(self) -> Dict[str, Any]:
        return {
            'user_id': self.user_id,
            'email': self.email,
            'name': self.name,
        }

    @classmethod
    def from_dict(cls, data: Dict[str, Any]) -> 'FederatedLoginResponse':
        return cls(
            user_id=data['user_id'],
            email=data['email'],
            name=data['name'],
        )


def normalize_federated_login_response(response: Dict[str, Any]) -> FederatedLoginResponse:
    return FederatedLoginResponse.from_dict(response)

import os

from amazon_nova_sdk import NovaClient


class IdentityClient:
    def __init__(self):
        self.client = NovaClient(
            api_key=os.getenv('NOVA_API_KEY'),
            model_id='amazon-nova-api/nova-pro-v1'
        )

    def federated_login(self, provider, token):
        response = self.client.federated_login(
            provider=provider,
            token=token
        )
        return response

import os
import flask
from google.oauth2 import id_token
from google.auth.transport import requests

app = flask.Flask(__name__)

@app.route('/oauth_callback')
def oauth_callback():
    code = flask.request.args.get('code')
    try:
        token = id_token.verify_oauth2_token(code, requests.Request(), os.getenv('GOOGLE_CLIENT_ID'))
        return flask.jsonify({'access_token': token['access_token']})
    except ValueError:
        return flask.jsonify({'error': 'Invalid token'}), 400

if __name__ == '__main__':
    app.run()
